const CHAPTER_TITLES = ["Introduction", "SDK environment setup", "Agentic loop foundations", "Multi-agent orchestration", "Advanced agent patterns", "Sessions, context & state", "Configuration, permissions & safety", "Built-in tooling", "Reliability & output quality", "Scaling context", "MCP ecosystem integration", "Claude Code in CI/CD", "Scenario-based architecture"];

// Starter block: one item per course chapter, in chapter order, so the chapter list
// and the practice panel stay index-aligned.
const STARTER_BLOCK_IDS = [1, 11, 2, 6, 15, 25, 46, 36, 70, 87, 32, 51, 23];
export const examQuestions: ExamQuestion[] = STARTER_BLOCK_IDS.map(
  (id, index) => {
    const question = examBank.find((item) => item.id === id) as ExamQuestion;
    return { ...question, chapter: CHAPTER_TITLES[index] };
  },
);


// Build a fresh block weighted by the published blueprint. Pass a seed for a
// repeatable block, omit it for a new draw each time.
export function buildWeightedBlock(size = 13, seed = Date.now()): ExamQuestion[] {
  let state = seed >>> 0;
  const rand = () => ((state = (state * 1664525 + 1013904223) >>> 0) / 4294967296);
  const picked: ExamQuestion[] = [];
  (Object.keys(domains) as DomainId[]).forEach((domain) => {
    const target = Math.max(1, Math.round((domains[domain].weight / 100) * size));
    const pool = examBank.filter((question) => question.domain === domain);
    for (let i = pool.length - 1; i > 0; i -= 1) {
      const j = Math.floor(rand() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    picked.push(...pool.slice(0, target));
  });
  for (let i = picked.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rand() * (i + 1));
    [picked[i], picked[j]] = [picked[j], picked[i]];
  }
  return picked.slice(0, size);
}
